select p.category, date_trunc('MONTH', p.launch_date) as launch_month, count(oi.unit_price) as unit_price_count, max(oi.unit_price) as max_unit_price from order_items oi inner join products p on oi.product_id = p.id where p.product_name like '%Hub%' group by p.category, date_trunc('MONTH', p.launch_date) having unit_price_count > 1 order by max_unit_price desc, category, launch_month limit 5;
